from typing import Final

import pytest

DEFAULTS: Final[tuple[tuple[str, str], ...]] = (("mode", "fast"), ("level", "3"))


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys/values on DEFAULTS and return the resulting values.

    Output order: mode, level, then any other keys in order of first appearance.
    keys[i] is set to values[i]; a later duplicate key overrides an earlier one.
    Raises ValueError if keys and values differ in length.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    merged: dict[str, str] = dict(DEFAULTS)
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    return list(merged.values())


def test_settings_defaults_only() -> None:
    assert settings([], []) == ["fast", "3"]


def test_settings_override_defaults() -> None:
    assert settings(["level", "mode"], ["5", "slow"]) == ["slow", "5"]


def test_settings_extra_keys_keep_given_order() -> None:
    assert settings(["x", "y"], ["1", "2"]) == ["fast", "3", "1", "2"]


def test_settings_duplicate_key_last_wins() -> None:
    assert settings(["x", "x"], ["1", "2"]) == ["fast", "3", "2"]


def test_settings_does_not_mutate_defaults() -> None:
    settings(["mode"], ["slow"])
    assert settings([], []) == ["fast", "3"]


def test_settings_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["mode", "level"], ["slow"])
